import test from 'node:test';import assert from 'node:assert/strict';import {defaultJacc,normalizeJaccBuilder,jaccBuilderAction,jaccBuilderView,activeCustomJacc,jaccSlots,jaccPaints,jaccLayerKeys,jaccLayerKey,jaccPartSvg,jaccSvg,customJaccTool,jaccMatchIndex} from '../src/jacc-builder.js';import {roster} from '../src/data.js';
const action=(s,a)=>jaccBuilderAction(s,a).builder;
test('custom mixed suits keep independent pieces, colors and job tools without changing the canonical nine',()=>{const original=JSON.stringify(roster);let s=normalizeJaccBuilder();s=action(s,{type:'paint',slot:'helmet',value:'orange'});s=action(s,{type:'paint',slot:'armor',value:'blue'});s=action(s,{type:'paint',slot:'boots',value:'yellow'});s=action(s,{type:'part',slot:'core',value:'ecosystems'});s=action(s,{type:'part',slot:'left',value:'math'});s=action(s,{type:'part',slot:'right',value:'geology'});assert.equal(customJaccTool(s.draft,'core').power,'connection-vision');assert.equal(customJaccTool(s.draft,'left').power,'pattern-vision');assert.equal(customJaccTool(s.draft,'right').target,'grounds-dig');assert.deepEqual([s.draft.colors.helmet,s.draft.colors.armor,s.draft.colors.boots],['orange','blue','yellow']);assert.equal(jaccMatchIndex(s.draft,roster),8);const green=action(s,{type:'paint',slot:'armor',value:'green'});assert.equal(jaccMatchIndex(green.draft,roster),1);assert.equal(JSON.stringify(roster),original);assert.equal(roster[8][0],'Chen Yuxin');});
test('saving, switching, editing and undo preserve saved designs until another explicit save',()=>{let s=action({}, {type:'save'}),old=JSON.stringify(s.models[0]);assert.equal(activeCustomJacc(s).id,'c1');s=action(s,{type:'paint',slot:'armor',value:'red'});assert.equal(JSON.stringify(s.models[0]),old);s=action(s,{type:'undo'});assert.equal(s.draft.colors.armor,'blue');s=action(s,{type:'new'});s=action(s,{type:'identity',field:'name',value:'Nova'});s=action(s,{type:'save'});assert.equal(s.models.length,2);s=action(s,{type:'play',id:'c1'});assert.equal(activeCustomJacc(s).name,'My Astronaut');s=action(s,{type:'edit',id:'c2'});s=action(s,{type:'paint',slot:'boots',value:'green'});s=action(s,{type:'save'});assert.equal(s.models.length,2);assert.equal(s.models[1].colors.boots,'green');assert.deepEqual(normalizeJaccBuilder(JSON.parse(JSON.stringify(s))),s);});
test('names and nationality can be optional or entered by taps, including spaces and an empty draft',()=>{let s=action({}, {type:'identity',field:'name',value:''});assert.equal(s.draft.name,'');for(const value of ['A','space','B'])s=action(s,{type:'key',field:'name',value,page:0});assert.equal(s.draft.name,'A B');s=action(s,{type:'key',field:'name',value:'delete'});assert.equal(s.draft.name,'A ');s=action(s,{type:'key',field:'name',value:'C'});assert.equal(s.draft.name,'A C');s=action(s,{type:'save'});assert.equal(s.models[0].name,'A C');assert.equal(s.models[0].country,'');assert.equal('gender' in s.models[0],false);assert.equal(jaccBuilderAction({}, {type:'save'}).play,true);});
test('invalid and old local data recovers; eight saved designs are bounded and never overwritten implicitly',()=>{let s=normalizeJaccBuilder({draft:{parts:{helmet:'bad'},colors:{armor:'bad'}},models:[{id:'c1',name:'A'},{id:'c1'},{id:'c9'}],activeId:'bad'});assert.equal(s.models.length,1);assert.equal(s.activeId,null);assert.equal(s.draft.parts.helmet,'round');assert.equal(s.draft.colors.armor,'blue');for(let i=1;i<8;i++){s=action(s,{type:'new'});s=action(s,{type:'save'});}assert.equal(s.models.length,8);const old=JSON.stringify(s.models);s=action(s,{type:'new'});const r=jaccBuilderAction(s,{type:'save'});assert.equal(r.play,false);assert.equal(JSON.stringify(r.builder.models),old);assert.deepEqual(normalizeJaccBuilder(null),normalizeJaccBuilder());});
test('all equipment/color variations render distinctly, and paged menus plus the tap keyboard fit native controls',()=>{let s=normalizeJaccBuilder();const original=jaccSvg(s.draft);for(const [slot,cfg]of Object.entries(jaccSlots)){for(const value of cfg.options){const d=action(s,{type:'part',slot,value}).draft;assert.ok(jaccLayerKeys[slot].includes(jaccLayerKey(d,slot)));if(value!==s.draft.parts[slot])assert.notEqual(jaccSvg(d),original,slot+value);}for(const value of Object.keys(jaccPaints)){const d=action(s,{type:'paint',slot,value}).draft;if(value!==s.draft.colors[slot])assert.notEqual(jaccSvg(d),original,slot+value);}}
const routes=['home','identity','name','country','face','skin','skin:1','countries:0','countries:3','parts:0','parts:1','parts:2','colors:0','colors:1','colors:2','library:0','undo',...Array.from({length:9},(_,i)=>'keys:name:'+i),...Object.keys(jaccSlots).flatMap(slot=>['slot:'+slot,...Array.from({length:4},(_,i)=>'options:'+slot+':'+i),...Array.from({length:3},(_,i)=>'paint:'+slot+':'+i)])];for(const route of routes){const v=jaccBuilderView(s,route);assert.ok(v.title&&v.text&&v.design);assert.ok(v.actions.length<=6,route);assert.ok(v.text.replace(/(.{1,43})(?:\s|$)/g,'$1\n').trim().split('\n').length<=7,route);}for(const key of Object.values(jaccLayerKeys).flat())assert.match(jaccPartSvg(key),/viewBox="0 0 120 160"/);});
